command:
/**
 * SVA example: Whirl Toggle
 * A whirling circle under each selected token: intro, then a persistent loop that follows the
 * token. Run again to stop it; the outro plays as it ends.
 *
 * Usage: select tokens, run.
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

const KIND = "whirl";
const COLOR = "blue"; // blue, green, orange, purple, red, red02, yellow, dark_black
const SCALE = 1.5;
const base = `jb2a.template_circle.${KIND}`;

const tokens = canvas.tokens.controlled;
if (!tokens.length) return ui.notifications.warn("Select at least one token.");
const sceneId = canvas.scene.id;

for (const tok of tokens) {
  const name = `sva-${KIND}:${tok.id}`;
  const seq = SVA.sequence();
  if (SVA.effects.list({ sceneId, name }).length) {
    // Stop the loop and play the outro in its place.
    await SVA.effects.end({ name, sceneId });
    seq.effect().file(`${base}.outro.${COLOR}`).attachTo(tok.id).scaleToObject(SCALE).layer("belowTokens");
    await seq.play();
    continue;
  }
  seq
    .effect()
    .file(`${base}.intro.${COLOR}`)
    .attachTo(tok.id)
    .scaleToObject(SCALE)
    .layer("belowTokens")
    .waitUntilFinished(-1000);
  seq
    .effect()
    .file(`${base}.loop.${COLOR}`)
    .attachTo(tok.id)
    .scaleToObject(SCALE)
    .layer("belowTokens")
    .fadeIn(500)
    .fadeOut(500)
    .persist(true)
    .name(name);
  await seq.play();
}
